import React, { useState } from 'react';

// Define the useToggle custom hook function
function useToggle(initial: boolean): [boolean, () => void] {
  const [state, setState] = useState<boolean>(initial);
  const toggle = () => {
    setState(prev => !prev);
  };
  return [state, toggle];
}

